import numpy as np
from scipy.optimize import minimize
from rdkit import Chem
from rdkit.Chem import AllChem
import math, json

lig=Chem.AddHs(Chem.MolFromSmiles('CC(C)c1cccc(C(C)C)c1N(P(c1ccccc1)c1ccccc1)[Ge](Cl)Cl'))
AllChem.EmbedMultipleConfs(lig,numConfs=16,randomSeed=777,pruneRmsThresh=0.45)
for cf in lig.GetConformers(): AllChem.UFFOptimizeMolecule(lig,confId=cf.GetId(),maxIters=1000)
nlig=lig.GetNumAtoms(); N=12;P=13;Ge=26
Irg=56;Irp=57;Cl=58

# generic restraint contribution and derivative
class Terms:
 def __init__(self): self.bonds=[];self.angs=[];self.reps=[];self.plans=[]
 def bond(self,i,j,d,k=140):self.bonds.append((i,j,d,k))
 def angle(self,i,j,k,deg,weight=90):self.angs.append((i,j,k,np.cos(np.deg2rad(deg)),weight))
 def calc(self,x):
  x=np.asarray(x).reshape(-1,3); g=np.zeros_like(x);e=0.
  for i,j,d,k in self.bonds:
   v=x[i]-x[j];r=np.linalg.norm(v);dr=r-d;e+=k*dr*dr;gg=(2*k*dr/r)*v;g[i]+=gg;g[j]-=gg
  for i,j,k,c0,w in self.angs:
   u=x[i]-x[j];v=x[k]-x[j];ru=np.linalg.norm(u);rv=np.linalg.norm(v);uu=u/ru;vv=v/rv;c=uu@vv;dc=c-c0;e+=w*dc*dc
   gi=2*w*dc*(vv-c*uu)/ru;gk=2*w*dc*(uu-c*vv)/rv;g[i]+=gi;g[k]+=gk;g[j]-=gi+gk
  if self.reps:
   a=np.array(self.reps);ii=a[:,0].astype(int);jj=a[:,1].astype(int);r0=a[:,2];w=a[:,3]
   v=x[ii]-x[jj];r=np.linalg.norm(v,axis=1);dr=np.minimum(r-r0,0.);e+=np.sum(w*dr*dr);gv=(2*w*dr/np.maximum(r,0.01))[:,None]*v
   np.add.at(g,ii,gv);np.add.at(g,jj,-gv)
  return e,g

def make_core():
 t=Terms()
 t.bond(Ge,Irg,2.42,200);t.bond(P,Irp,2.28,200);t.bond(Irg,Cl,2.43,200);t.bond(Irp,Cl,2.43,200)
 for a in [N,27,28]:t.angle(a,Ge,Irg,109.47,120)
 for a in [N,14,20]:t.angle(a,P,Irp,109.47,110)
 # planar nitrogen
 for i,j in [(11,P),(11,Ge),(P,Ge)]:t.angle(i,N,j,120,220)
 t.angle(Ge,Irg,Cl,90,200);t.angle(P,Irp,Cl,90,200);t.angle(Irg,Cl,Irp,100,55)
 # repulsion between metals/bridge Cl and ligand. Donor 1-3 pairs ignored; handle additional contacts mildly
 radii={'C':1.60,'H':1.08,'N':1.5,'P':1.8,'Ge':1.8,'Cl':1.75,'Ir':1.45}
 sym=[a.GetSymbol() for a in lig.GetAtoms()]+['Ir','Ir','Cl']
 skip={(Ge,Irg),(P,Irp),(Irg,Cl),(Irp,Cl)}
 for j in range(nlig,59):
  for i in range(j):
   if (i,j) in skip:continue
   r=radii[sym[i]]+radii[sym[j]]
   if j==Irg and i in [N,27,28]: r=2.6
   if j==Irp and i in [N,14,20]:r=2.6
   t.reps.append((i,j,r,25))
 return t

ff=AllChem.UFFGetMoleculeForceField(lig,confId=0)
core=make_core()
def optimize(x,ffs,terms,maxiter=1200):
 def fun(vec):
  xyz=vec.reshape(-1,3); e,g=terms.calc(xyz)
  for ff,sl in ffs:
   v=xyz[sl].ravel().tolist();e+=ff.CalcEnergy(v);g[sl]+=np.array(ff.CalcGrad(v)).reshape(-1,3)
  return e,g.ravel()
 res=minimize(fun,x.ravel(),jac=True,method='L-BFGS-B',options={'maxiter':maxiter,'ftol':1e-10,'gtol':2e-4,'maxls':40})
 return res.x.reshape(-1,3),res.fun,res

results=[]
for cid,cf in enumerate(lig.GetConformers()):
 xlig=np.array(cf.GetPositions())
 pdir=-sum((xlig[i]-xlig[P])/np.linalg.norm(xlig[i]-xlig[P]) for i in [N,14,20]);pdir/=np.linalg.norm(pdir)
 gdir=-sum((xlig[i]-xlig[Ge])/np.linalg.norm(xlig[i]-xlig[Ge]) for i in [N,27,28]);gdir/=np.linalg.norm(gdir)
 ip=xlig[P]+2.28*pdir;ig=xlig[Ge]+2.42*gdir
 for seed in range(2):
  rng=np.random.default_rng(cid*7+seed)
  mid=(ip+ig)/2; c=mid+np.cross(ip-ig,xlig[P]-xlig[Ge]);v=c-mid
  if np.linalg.norm(v)>0:c=mid+(-1 if seed==0 else 1)*1.7*v/np.linalg.norm(v)
  else:c=mid+rng.normal(size=3)
  x=np.vstack([xlig,ig,ip,c]); x,e,res=optimize(x,[(ff,slice(0,56))],core,1000)
  results.append((e,x));print('core',cid,seed,e,res.success,flush=True)
results.sort(key=lambda a:a[0]);np.save('core.npy',results[0][1]);print('best',results[0][0])
np.savez('cores.npz',**{'c'+str(i):x for i,(e,x) in enumerate(results[:8])})
